fn main() {
    // Deux façons de créer un vecteur vide, équivalentes :
    let mut scores: Vec<i32> = Vec::new();
    scores.push(10);              // on ajoute un élément à la fin
    scores.push(20);
    scores.push(30);

    // La macro `vec!` crée un vecteur déjà rempli :
    let notes = vec![12, 15, 9]; // Rust devine le type : Vec<i32>

    println!("{:?}", scores);     // affiche : [10, 20, 30]
    println!("{:?}", notes);      // affiche : [12, 15, 9]
}

fn main() {
    let notes = vec![12, 15, 9];

    // Accès direct : pratique, mais panique si l'index est hors bornes
    let premiere = notes[0];
    println!("Premiere note : {premiere}"); // 12

    // Accès sûr avec .get() : renvoie une Option
    match notes.get(10) {
        Some(valeur) => println!("Trouvee : {valeur}"),
        None => println!("Aucune note a cet index"), // ce cas s'affiche
    }

    // notes[10] ici ferait paniquer le programme :
    // thread 'main' panicked ... index out of bounds
}

fn main() {
    let mut notes = vec![12, 15, 9];

    // Lecture : on emprunte avec &notes, le vecteur reste disponible
    for n in &notes {
        println!("note = {n}");
    }

    // Écriture : on emprunte avec &mut pour modifier chaque élément
    for n in &mut notes {
        *n += 1;          // `*n` accède à la valeur derrière la référence
    }

    println!("{:?}", notes); // affiche : [13, 16, 10]
}

use std::collections::HashMap; // import obligatoire

fn main() {
    let mut scores: HashMap<String, i32> = HashMap::new();

    scores.insert(String::from("Ada"), 10);   // associe la cle a la valeur
    scores.insert(String::from("Linus"), 7);

    // .get() renvoie une Option : Some(&valeur) si la cle existe, sinon None
    match scores.get("Ada") {
        Some(points) => println!("Ada : {points}"), // Ada : 10
        None => println!("Joueur inconnu"),
    }

    // .get() d'une cle absente donne None, pas de panique :
    println!("{:?}", scores.get("Bob")); // affiche : None
}

use std::collections::HashMap;

fn main() {
    let texte = "le chat le chien le chat";
    let mut comptes: HashMap<&str, i32> = HashMap::new();

    for mot in texte.split_whitespace() {
        // or_insert(0) cree l'entree a 0 si absente, et renvoie &mut vers la valeur
        let compte = comptes.entry(mot).or_insert(0);
        *compte += 1; // on incremente via la reference mutable
    }

    // {:#?} affiche joliment, sur plusieurs lignes
    println!("{:#?}", comptes); // le -> 3, chat -> 2, chien -> 1
}

fn main() {
    // Construction par ajouts successifs
    let mut phrase = String::from("Bonjour");
    phrase.push_str(", monde"); // ajoute un fragment a la fin
    phrase.push('!');            // ajoute un seul caractere
    println!("{phrase}");        // Bonjour, monde!

    // Construction directe avec format! (renvoie une String)
    let nom = "Ada";
    let age = 36;
    let carte = format!("{nom} a {age} ans");
    println!("{carte}");         // Ada a 36 ans
}

