On insère chaque mot dans la `HashMap` et on incrémente son compteur via la référence mutable renvoyée par `or_insert`. On transforme chaque `&str` en `String` avec `.to_string()` pour que la table possède ses propres clés.

```rust
use std::collections::HashMap;

fn compter_mots(texte: &str) -> HashMap<String, i32> {
    let mut comptes: HashMap<String, i32> = HashMap::new();
    for mot in texte.split_whitespace() {
        // or_insert(0) cree l'entree si absente, puis renvoie &mut vers la valeur
        let compte = comptes.entry(mot.to_string()).or_insert(0);
        *compte += 1;
    }
    comptes
}

fn main() {
    let resultat = compter_mots("rouge vert rouge bleu vert rouge");
    println!("{:#?}", resultat); // rouge -> 3, vert -> 2, bleu -> 1
}
```
